use crate::*;
use crate::{NativeDefault,NativeDefaultCursor};
struct Bank{g:RetainedCloneGrant,fuel:u64,maximum:u64,work:u64}
impl Bank{fn new()->Self{let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];Self{g:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},fuel:s["fuel"].as_u64().unwrap(),maximum:s["maximumTurns"].as_u64().unwrap(),work:0}}fn offer(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.g.maximum_items.min(1),..self.g}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.g));assert!(work<=self.fuel);self.g.maximum_items-=p.copied_items;self.g.maximum_copy_bytes-=p.copied_bytes;self.g.maximum_capacity_bytes-=p.retained_capacity_bytes;self.g.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(work).unwrap();self.work+=work;}fn retire<T:RetireOwned>(&mut self,value:T){let mut retirement_actual=None;let mut retirement_work=0;let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..self.maximum{if owner.terminal_is_empty()&&retirement_actual.is_none(){break}assert!(owner.next_computational_work(self.offer().maximum_copy_bytes).unwrap()<=self.fuel);let(s,heap)=crate::observe_retirement_allocations(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,self.offer(),self.fuel,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result}.unwrap());let p=s.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.post(p,retirement_work);}assert!(owner.terminal_is_empty());}}

fn fixture_cursor<T:NativeDefault>(bank:&mut Bank)->T::Cursor{
 let mut output=None;let mut actual=None;let grant=bank.offer();assert!(T::default_cursor_work_demand().unwrap()<=bank.fuel);assert!(crate::retained_clone::retained_clone_grant_admits(grant,T::default_cursor_demand()));let(turn,heap)=crate::observe_retirement_allocations(||T::default_cursor(&mut output,grant,Some(&mut actual)));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));if let Some(bytes)=actual{assert_eq!(bytes,heap.0)}else{assert_eq!(heap.0,0)}bank.post(p,turn.work);turn.result.unwrap();
 if actual.is_some(){let g=bank.offer();let demand=RetirementDemand{copy_bytes:std::mem::size_of::<Option<usize>>(),depth:1,..Default::default()};assert!(bank.fuel>=1&&crate::retained_clone::retained_clone_grant_admits(g,demand));actual=None;bank.post(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()},1)}assert!(actual.is_none());assert!(bank.fuel>=1);let value=output.take().unwrap();bank.post(RetainedCloneProgress{copied_items:1,..Default::default()},1);value
}

fn run<T:NativeDefault>(cut:Option<u64>,check:impl FnOnce(&T))->u64{let mut bank=Bank::new();let mut cursor=fixture_cursor::<T>(&mut bank);let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let mut null_seen=false;for _ in 0..cut.unwrap_or(bank.maximum){if cursor.output_ready(){break}let d=cursor.demands(4096,bank.fuel).unwrap();let g=bank.offer();for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.depth>0).then_some(RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,denied,crate::source_fixture::WorkLoan::new(&bank.fuel,bank.fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,denied)}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}if d.capacity_bytes>0&&!null_seen{let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&bank.fuel,bank.fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,g)})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let p=turn.result.as_ref().err().unwrap().retained_progress();bank.post(p,turn.work);bank.retire(turn.result.err().unwrap());null_seen=true;continue}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&bank.fuel,bank.fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,g)}));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);}let normal_work=bank.work;if cut.is_none(){assert!(cursor.output_ready());let(turn,heap)=crate::observe_retirement_allocations(||cursor.take(bank.offer()));let(output,p)=turn.result.unwrap().unwrap();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);check(&output);bank.retire(output);}cursor.begin_close();let mut actual=None;for _ in 0..bank.maximum{if cursor.terminal_is_empty()&&actual.is_none(){break}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,bank.offer(),bank.fuel,cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);}assert!(cursor.terminal_is_empty());assert_eq!(crate::source_fixture::close_step(&mut actual,Default::default(),bank.fuel,cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)).work,0);normal_work}
#[test]fn actual_native_default_array_and_tuple_are_owned_phased_and_match_independent_serde(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();run::<[f64;3]>(None,|v|assert_eq!(serde_json::to_value(v).unwrap(),law["smallArray"]));run::<(String,bool)>(None,|v|assert_eq!(serde_json::to_value(v).unwrap(),law["tuple"]));for cut in law["cancelCuts"].as_array().unwrap(){run::<[String;3]>(Some(cut.as_u64().unwrap()),|_|{});}}
#[test]fn actual_native_default_large_zero_sized_array_cannot_collapse_into_one_cpu_turn(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let work=run::<[();4097]>(None,|v|{assert_eq!(v.len(),law["largeZeroSizedCount"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_value(v.iter().collect::<Vec<_>>()).unwrap(),serde_json::json!(vec![serde_json::Value::Null;4097]));});assert!(work>=law["minimumLargeWork"].as_u64().unwrap());}
#[test]fn actual_native_empty_array_default_returns_the_real_empty_value(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();run::<[u8;0]>(None,|value|assert_eq!(serde_json::to_value(value).unwrap(),law["emptyArray"]));}

#[test]fn actual_default_leaf_payload_writes_differ_from_empty_owner_headers(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);macro_rules! check{($ty:ty,$kind:literal,$expected:expr)=>{{let mut cursor=fixture_cursor::<$ty>(&mut bank);let d=cursor.demands(4096,bank.fuel).unwrap();assert_eq!(d.copy_bytes,std::mem::size_of::<Option<$ty>>());if d.copy_bytes>0{let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank.offer()},crate::source_fixture::WorkLoan::new(&bank.fuel,bank.fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank.offer()})}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(!cursor.output_ready());}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::receive(&mut control,bank.offer(),crate::source_fixture::WorkLoan::new(&bank.fuel,bank.fuel),|native|{let maximum=native.available_work_units().unwrap();cursor.advance(native,4096,maximum,bank.offer())}));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(heap,(0,0));bank.post(p,turn.work);let turn=cursor.take(bank.offer());let(value,p)=turn.result.unwrap().unwrap();bank.post(p,turn.work);assert_eq!(value,$expected);assert_eq!(serde_json::to_value(&value).unwrap(),law["freshDefaultValues"][$kind]);bank.retire(value);cursor.begin_close();let mut actual=None;assert!(cursor.terminal_is_empty());}};}check!(bool,"bool",false);check!(u64,"u64",0);check!(f64,"f64",0.0);check!(String,"string",String::new());check!((),"unit",());}

#[test]fn zero_work_default_does_not_start_original_effect(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️admission/🔣️.json")).unwrap();for row in f["cases"].as_array().unwrap().iter().filter(|r|r["kind"]=="boolean"&&r["budget"]==0){let mut bank=Bank::new();let mut header=None;let(turn,heap)=crate::observe_retirement_allocations(||bool::default_cursor(&mut header,bank.offer(),None));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work);let mut cursor=header.take().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let(turn,heap)=crate::observe_retirement_allocations(||cursor.advance(&mut control,4096,row["budget"].as_u64().unwrap(),bank.offer()));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(!cursor.output_ready());cursor.begin_close().unwrap();let mut actual=None;assert!(cursor.terminal_is_empty());}}

#[test]fn interrupted_default_receipt_keeps_output_until_original_settlement(){use crate::native_decoding::{NativeConstructionRecipientIssuer,NativeDecodeConstructionRecipient,NativeDecodeWorkIssuer,NativeDecodeWorkRecipient};use crate::native_decoding::construction::NativeRecoveryLoan;struct Recipient{accepted:RetainedCloneProgress,interrupt:bool}impl NativeDecodeConstructionRecipient for Recipient{fn submitted(&self)->RetainedCloneProgress{self.accepted}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth})}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));self.accepted=p;if self.interrupt{self.interrupt=false;panic!("committed original receipt interrupted")}Ok(())}}struct Fuel;impl NativeDecodeWorkRecipient for Fuel{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{1u64.checked_sub(observed).ok_or_else(||ValueError::invariant("one-unit original work exhausted"))}fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|work|work<=1))}}let f:serde_json::Value=serde_json::from_str(include_str!("../../../../🏭️construction/📦️effect/🧪️fixtures/🛟️recovery/🔣️.json")).unwrap();assert_eq!(f["cases"].as_array().unwrap().iter().find(|v|v["phase"]=="ReceiptStarted").unwrap()["outputAllowed"],false);let mut bank=Bank::new();let mut header=None;let turn=bool::default_cursor(&mut header,bank.offer(),None);bank.post(turn.result.unwrap().progress(),turn.work);let mut cursor=header.take().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let mut recipient=Recipient{accepted:Default::default(),interrupt:true};let mut issuer=NativeConstructionRecipientIssuer::new();let mut loan=issuer.loan(&mut recipient);let mut fuel=Fuel;let mut work_issuer=NativeDecodeWorkIssuer::new();let mut work=work_issuer.loan(&mut fuel);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||control.with_work_recipient(&mut work,|control|control.with_construction_recipient(&mut loan,|control|Ok::<_,ValueError>(cursor.advance(control,4096,1,bank.offer()))))));assert!(interrupted.is_err());assert!(cursor.has_pending_recovery());assert!(!cursor.output_ready());assert!(cursor.take(bank.offer()).result.unwrap().is_none());assert!(cursor.begin_close().is_err());let resumed=control.with_work_recipient(&mut work,|control|control.with_construction_recipient(&mut loan,|control|{match cursor.pending_recovery().unwrap(){NativeRecoveryLoan::Value(frame)=>frame.resolve_receipt(control,Ok(())).map_err(|(error,receipt)|{assert!(receipt.is_ok());error})?,NativeRecoveryLoan::Retirement(_)=>return Err(ValueError::invariant("unexpected retirement frame"))}Ok::<_,ValueError>(cursor.resume_recovery(control))})).unwrap();let progress=resumed.result.unwrap();bank.post(progress,resumed.work);assert!(cursor.output_ready());drop(work);assert!(!work_issuer.has_pending_work());let turn=cursor.take(bank.offer());let(output,p)=turn.result.unwrap().unwrap();bank.post(p,turn.work);assert!(!output);cursor.begin_close().unwrap();let mut actual=None;assert!(cursor.terminal_is_empty());}

#[test]fn default_effect_honors_both_original_grants(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️grants/🔣️.json")).unwrap();let parse=|row:&serde_json::Value|{let a=row.as_array().unwrap();RetainedCloneGrant{maximum_items:a[0].as_u64().unwrap() as usize,maximum_copy_bytes:a[1].as_u64().unwrap() as usize,maximum_capacity_bytes:a[2].as_u64().unwrap() as usize,maximum_release_bytes:a[3].as_u64().unwrap() as usize,maximum_depth:a[4].as_u64().unwrap() as usize}};for row in f["cases"].as_array().unwrap(){let actual=parse(&row["caller"]).restricted_by(parse(&row["recipient"]));assert_eq!(actual,parse(&row["expected"]));}}

#[test]fn missing_original_recipient_leaves_default_retryable(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️outcome/🔣️.json")).unwrap();assert_eq!(f["cases"].as_array().unwrap().iter().find(|c|c["outcome"]=="pre_effect_refusal").unwrap()["retryable"],true);let mut bank=Bank::new();let mut output=None;let turn=bool::default_cursor(&mut output,bank.offer(),None);bank.post(turn.result.unwrap().progress(),turn.work);let mut cursor=output.take().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let turn=cursor.advance(&mut control,4096,1,bank.offer());assert_eq!(turn.work,0);let error=turn.result.unwrap_err();assert!(!cursor.output_ready());assert!(!cursor.has_pending_recovery());assert_eq!(cursor.advance_work_demand(4096,1).unwrap(),1);bank.retire(error);cursor.begin_close().unwrap();let mut actual=None;assert!(cursor.terminal_is_empty());}

#[test]fn refused_default_receipt_keeps_output_for_paid_close(){use crate::native_decoding::{NativeConstructionRecipientIssuer,NativeDecodeConstructionRecipient,NativeDecodeWorkIssuer,NativeDecodeWorkRecipient};struct Recipient;impl NativeDecodeConstructionRecipient for Recipient{fn submitted(&self)->RetainedCloneProgress{Default::default()}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth})}fn accept(&mut self,_:RetainedCloneGrant,_:RetainedCloneProgress)->Result<(),ValueError>{Err(ValueError::literal(crate::ValueRefusalKind::InvalidValue,"original receipt refused"))}}struct Fuel;impl NativeDecodeWorkRecipient for Fuel{fn available_work(&mut self,observed:u64)->Result<u64,ValueError>{1u64.checked_sub(observed).ok_or_else(||ValueError::invariant("original work exhausted"))}fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|work|work<=1))}}let f:serde_json::Value=serde_json::from_str(include_str!("🧫️outcome/🔣️.json")).unwrap();assert_eq!(f["cases"].as_array().unwrap().iter().find(|c|c["outcome"]=="failure").unwrap()["ready"],false);let mut bank=Bank::new();let mut output=None;let turn=bool::default_cursor(&mut output,bank.offer(),None);bank.post(turn.result.unwrap().progress(),turn.work);let mut cursor=output.take().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.g.maximum_capacity_bytes,&mut callback);let mut recipient=Recipient;let mut issuer=NativeConstructionRecipientIssuer::new();let mut loan=issuer.loan(&mut recipient);let mut fuel=Fuel;let mut work_issuer=NativeDecodeWorkIssuer::new();let mut work=work_issuer.loan(&mut fuel);let turn=control.with_work_recipient(&mut work,|control|control.with_construction_recipient(&mut loan,|control|Ok::<_,ValueError>(cursor.advance(control,4096,1,bank.offer())))).unwrap();let spent=turn.work;let error=turn.result.unwrap_err();assert_eq!(spent,1);let progress=error.retained_progress();assert_eq!(progress.copied_items,1);assert_eq!(progress.copied_bytes,std::mem::size_of::<bool>());assert_eq!(cursor.output.as_ref(),Some(&false));bank.post(progress,spent);assert!(!cursor.has_pending_recovery());assert!(!cursor.output_ready());assert!(cursor.take(bank.offer()).result.unwrap().is_none());drop(work);assert!(!work_issuer.has_pending_work());bank.retire(error);cursor.begin_close().unwrap();let mut actual=None;while (!cursor.terminal_is_empty()||actual.is_some())&&bank.fuel>0{let demand=cursor.close_work_demand(4096).unwrap();assert!(demand>0&&demand<=bank.fuel);let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,bank.offer(),bank.fuel,cursor.close_demands(4096),cursor.close_work_demand(4096),|g,a|cursor.close_step(g,a)));let p=turn.result.unwrap().progress();assert!(turn.work>0||cursor.terminal_is_empty());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,turn.work)}assert!(cursor.terminal_is_empty());}
